const part3Translations: Record<string, string> = {};

const GENERATED_PART3_QUESTIONS = PART3_PACKS.flatMap((pack, packIndex) => {
  const base = 51 + packIndex * 4;
  const makeId = (offset: number) => `p3-${String(base + offset).padStart(2, "0")}`;
  const items = [
    { id: makeId(0), question: `Why has ${pack.subject} become an important issue?`, answer: `${pack.trend.charAt(0).toUpperCase() + pack.trend.slice(1)}. This matters because ${pack.benefit}. For example, ${pack.example}. But honestly, the discussion should also admit that ${pack.limit}.`, zh: `${pack.zh[0]}。这很重要，因为${pack.zh[1]}。例如，${pack.zh[3]}。不过，讨论也应承认${pack.zh[5]}。` },
    { id: makeId(1), question: `What are the main benefits of ${pack.subject}?`, answer: `The strongest benefit is that ${pack.benefit}. ${pack.example.charAt(0).toUpperCase() + pack.example.slice(1)}. The real value shows up when the benefit keeps coming, not just through one short project. Even so, ${pack.limit}.`, zh: `最主要的好处是${pack.zh[1]}。${pack.zh[3]}。只有稳定提供而不是短期项目时，这种更广价值才会出现。即便如此，${pack.zh[5]}。` },
    { id: makeId(2), question: `What problems can be associated with ${pack.subject}?`, answer: `A major problem is that ${pack.risk}. That can turn a seemingly positive change into inequality or distrust. ${pack.example.charAt(0).toUpperCase() + pack.example.slice(1)}. The risk can be lowered, though ${pack.limit}.`, zh: `主要问题是${pack.zh[2]}。这会把看似积极的变化变成不平等或不信任的来源。${pack.zh[3]}。风险可以降低，但${pack.zh[5]}。` },
    { id: makeId(3), question: `What should governments or organisations do about ${pack.subject}?`, answer: `A practical response is that ${pack.response}. The policy should fix the underlying system, not ask individuals to solve everything on their own. ${pack.example.charAt(0).toUpperCase() + pack.example.slice(1)}. Still, ${pack.limit}.`, zh: `实际回应可以是${pack.zh[4]}。政策应处理底层系统，而不是要求个人独自解决一切。${pack.zh[3]}。不过，${pack.zh[5]}。` },
  ];
  for (const item of items) part3Translations[item.id] = item.zh;
  return items.map((item) => ({
    id: item.id,
    topic: pack.topic,
    question: item.question,
    answer: item.answer,
    phrases: [...pack.phrases],
    coaching: "立场 → 原因 → 例子 → 限定：先直接回答，再解释机制，用具体场景支撑，最后说明适用边界。",
  }));
});

export const ADDITIONAL_PART3_QUESTIONS = GENERATED_PART3_QUESTIONS.slice(0, 100);

const SELECTED_SPEAKING_IDS = new Set([
  ...ADDITIONAL_PART1_QUESTIONS.map((item) => item.id),
  ...ADDITIONAL_PART2_CUES.map((item) => item.id),
  ...ADDITIONAL_PART3_QUESTIONS.map((item) => item.id),
]);

export const ADDITIONAL_SPEAKING_TRANSLATIONS: Record<string, string> = Object.fromEntries(
  Object.entries({ ...part1Translations, ...part2Translations, ...part3Translations })
    .filter(([id]) => SELECTED_SPEAKING_IDS.has(id)),
);
